import { FeesApi } from '../supabase/domain-services';
import { NotificationsApi } from '../supabase/domain-services';
import { AcademyFacade } from './academy.facade';

export interface AcademyState {
  students: Student[];
  parents: Parent[];
  batches: Batch[];
  coaches: Coach[];
  enrollments: Enrollment[];
  attendance: AttendanceRecord[];
  charges: FeeCharge[];
  payments: Payment[];
  notifications: NotificationLog[];
}

@Injectable({
  providedIn: 'root',
})
export class AcademyStore {
  private readonly facade = inject(AcademyFacade);
  private readonly config = inject(API_CONFIG);

  // Signals initialize empty - loaded from Supabase when backend === 'supabase'
  students = signal<Student[]>([]);
  parents = signal<Parent[]>([]);
  batches = signal<Batch[]>([]);
  coaches = signal<Coach[]>([]);
  enrollments = signal<Enrollment[]>([]);
  attendance = signal<AttendanceRecord[]>([]);
  charges = signal<FeeCharge[]>([]);
  payments = signal<Payment[]>([]);
  notifications = signal<NotificationLog[]>([]);

  loading = signal<boolean>(false);
  apiError = signal<string>('');

  private initialized = false;

  constructor() {
    // If backend is supabase, initialize from API; otherwise signals stay empty
    if (this.config.backend === 'supabase') {
      this.initializeFromSupabase();
    }
  }

  /** Load all data from Supabase APIs in parallel */
  private async initializeFromSupabase(): Promise<void> {
    if (this.initialized) return;
    this.initialized = true;
    this.loading.set(true);
    this.apiError.set('');

    try {
      const [
        studentsResult,
        parentsResult,
        batchesResult,
        coachesResult,
        enrollmentsResult,
        attendanceResult,
        chargesResult,
      ] = await Promise.all([
        this.studentsApi.list(),
        this.parentsApi.list(),
        this.batchesApi.list(),
        this.coachesApi.list(),
        this.enrollmentsApi.list(),
        this.attendanceApi.list(),
        this.feesApi.charges(),
      ]);

      this.studentsState.set(studentsResult.data ?? []);
      this.parentsState.set(parentsResult.data ?? []);
      this.batchesState.set(batchesResult.data ?? []);
      this.coachesState.set(coachesResult.data ?? []);
      this.enrollmentsState.set(enrollmentsResult.data ?? []);
      this.attendanceState.set(attendanceResult ?? []);
      this.chargesState.set(chargesResult.data ?? []);
    } catch (error) {
      // On failure: fall back to empty state (not hardcoded mock data)
      this.studentsState.set([]);
      this.parentsState.set([]);
      this.batchesState.set([]);
      this.coachesState.set([]);
      this.enrollmentsState.set([]);
      this.attendanceState.set([]);
      this.chargesState.set([]);
      this.apiError.set(
        'Failed to load academy data from backend.',
      );
    } finally {
      this.loading.set(false);
    }
  }

  /** Academic year helper */
  private today(): string {
    return new Date().toISOString().split('T')[0];
  }

  /** Find a student by ID */
  getStudent(studentId: string): Student | undefined {
    return this.students().find((item: Student) => item.id === studentId);
  }

  /** Find a parent by ID */
  getParent(parentId: string): Parent | undefined {
    return this.parents().find((item: Parent) => item.id === parentId);
  }

  /** Find a batch by ID */
  getBatch(batchId: string): Batch | undefined {
    return this.batches().find((item: Batch) => item.id === batchId);
  }

  /** Find a coach by ID */
  getCoach(coachId: string): Coach | undefined {
    return this.coaches().find((item: Coach) => item.id === coachId);
  }

  /** Find enrollment by student and batch */
  getEnrollment(studentId: string, batchId: string): Enrollment | undefined {
    return this.enrollments().find(
      (item: Enrollment) => item.studentId === studentId && item.batchId === batchId,
    );
  }

  /** Queue attendance notification */
  queueAttendanceNotification(
    studentId: string,
    batchId: string,
    status: 'present' | 'absent' | 'late',
  ): void {
    // Trigger notification through facade
    this.facade.queueAttendanceNotification(studentId, batchId, status);
  }
}"}}


