/* Keep the history table sized to its own content instead of stretching to the
   correction rail, and give both columns a deliberate desktop balance. */
:host,
.history-page,
.history-layout,
.history-layout > main,
.history-layout > aside,
.records {
  min-width: 0;
}

.history-layout {
  grid-template-columns: minmax(0, 1fr) minmax(320px, 360px);
  align-items: start;
  gap: 18px;
}

.history-layout > main,
.history-layout > aside {
  align-self: start;
}

.history-layout > main {
  align-content: start;
}

.history-layout aside {
  gap: 16px;
}

.records {
  align-self: start;
  overflow: hidden;
  border-color: #dfe8e2;
  border-radius: 14px;
  box-shadow: 0 5px 20px rgba(22, 58, 37, 0.045);
}

.records .table-wrap {
  border: 0;
  border-radius: 0;
  background: #fff;
}

.table-filters {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;

  .search-field,
  .range-presets {
    grid-column: span 2;
  }
}

.side-card {
  border-color: #dfe8e2;
  border-radius: 14px;
  box-shadow: 0 5px 20px rgba(22, 58, 37, 0.045);
}

.side-card h2 {
  font-size: 15px;
}

@media (max-width: 1100px) {
  .history-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .history-layout aside {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .history-layout aside {
    grid-template-columns: minmax(0, 1fr);
  }

  .table-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));

    .search-field,
    .range-presets {
      grid-column: 1 / -1;
    }
  }
}
