/* Responsive calendar workspace */
.calendar-page {
  color: var(--app-text, #18352a);
}

.calendar-layout {
  gap: 18px;
}

.calendar-layout main {
  gap: 16px;
}

.calendar-filters {
  display: grid;
  grid-template-columns: repeat(4, minmax(130px, 1fr)) auto auto;
  align-items: end;
  gap: 12px;
  padding: 18px;
  border-color: var(--app-border, #dce5df);
  border-radius: 14px;
  box-shadow: 0 4px 18px rgba(22, 58, 37, 0.035);
}

.calendar-filters label {
  gap: 7px;
  color: var(--app-text, #24332b);
  font-size: 13px;
  font-weight: 600;
}

.calendar-filters select,
.calendar-filters input,
.calendar-filters button {
  box-sizing: border-box;
  min-width: 0;
  min-height: 44px;
  height: auto;
  padding: 9px 12px;
  border: 1px solid var(--app-border, #cbd8d0);
  border-radius: 8px;
  color: var(--app-text, #24332b);
  background: var(--app-card, #fff);
  font: inherit;
  font-size: 13px;
}

.calendar-filters select,
.calendar-filters input {
  width: 100%;
}

.calendar-filters .today-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--app-primary, #08743c);
  font-weight: 650;
  white-space: nowrap;
  cursor: pointer;
}

.calendar-filters .view-switch {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px;
  border: 1px solid var(--app-border, #dce5df);
  border-radius: 10px;
  background: #f5f8f6;
}

.calendar-filters .view-switch button {
  min-height: 36px;
  padding: 7px 13px;
  border-color: transparent;
  border-radius: 7px;
  background: transparent;
  color: #52645a;
  font-weight: 600;
  cursor: pointer;
}

.calendar-filters .view-switch button:hover:not(.active) {
  background: #eaf2ed;
  color: #17633b;
}

.calendar-filters .view-switch .active {
  color: #fff;
  background: var(--app-primary, #08743c);
  box-shadow: 0 2px 5px rgba(8, 116, 60, 0.2);
}

.calendar-filters :is(select, input, button):focus-visible {
  outline: 2px solid var(--app-primary, #08743c);
  outline-offset: 2px;
}

.main-calendar,
.list-view {
  overflow: hidden;
  border: 1px solid var(--app-border, #dce5df);
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(22, 58, 37, 0.035);
}

.main-calendar > header,
.list-view > header {
  justify-content: space-between;
  min-height: 64px;
  padding: 12px 18px;
  border-bottom: 1px solid #e8eeea;
}

.main-calendar .calendar-period {
  display: flex;
  align-items: center;
  gap: 12px;
}

.main-calendar .calendar-period h2,
.main-calendar header h2,
.list-view > header h2 {
  color: var(--app-text, #24332b);
  font-size: 18px;
  font-weight: 700;
}

.main-calendar .calendar-period .period-button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid var(--app-border, #dce5df);
  border-radius: 9px;
  color: #476154;
  background: #fff;
  cursor: pointer;
  transition: background 140ms ease, border-color 140ms ease;
}

.main-calendar .calendar-period .period-button:hover {
  border-color: #b7d3c2;
  color: #08743c;
  background: #f1f8f3;
}

.main-calendar .export,
.list-view > header .export {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  margin: 0;
  padding: 8px 13px;
  border: 1px solid var(--app-border, #dce5df);
  border-radius: 8px;
  color: #315541;
  background: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}

.main-calendar .export:hover,
.list-view > header .export:hover {
  border-color: #b7d3c2;
  background: #f5faf6;
}

.weekdays,
.month-grid {
  min-width: 0;
}

.weekdays {
  padding: 0 8px;
  background: #f7faf8;
}

.weekdays b {
  padding: 13px 8px;
  color: #617268;
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.035em;
  text-transform: uppercase;
}

.month-grid {
  border-top-color: #e8eeea;
}

.month-grid article {
  box-sizing: border-box;
  min-width: 0;
  min-height: 118px;
  padding: 11px 12px;
  border-right-color: #e8eeea;
  border-bottom-color: #e8eeea;
  background: #fff;
  color: #30463a;
  transition: background 120ms ease;
}

.month-grid article:nth-child(7n) {
  border-right: 0;
}

.month-grid article:not(.muted):hover {
  background: #fafcfb;
}

.month-grid strong {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  margin: -4px 0 9px -4px;
  border-radius: 50%;
  color: #31483a;
  font-size: 13px;
  font-weight: 700;
}

.month-grid .today {
  background: #f1f8f3;
}

.month-grid .today strong {
  margin: -4px 0 9px -4px;
  color: #fff;
  background: var(--app-primary, #08743c);
}

.month-grid .muted {
  background: #fbfcfb;
  color: #a2ada6;
}

.month-grid span {
  display: flex;
  align-items: center;
  gap: 2px;
  margin: 5px 0;
  color: #617268;
  font-size: 12px;
  line-height: 1.35;
}

.month-grid span i,
.legend li i {
  flex: 0 0 7px;
  width: 7px;
  height: 7px;
  margin-right: 6px;
}

.month-grid .present { color: #08743c; }
.month-grid .absent { color: #c43d42; }
.month-grid .late { color: #a96607; }
.month-grid .present i { background: #08743c; }
.month-grid .absent i { background: #dc474c; }
.month-grid .late i { background: #ed930f; }
.month-grid article > span:not(.present, .absent, .late) {
  color: #496276;
}

.month-grid article > small {
  margin-top: 12px;
  color: #87948c;
  font-size: 12px;
}

.month-grid em {
  padding: 4px 8px;
  border: 1px solid #f2d1ae;
  border-radius: 6px;
  color: #986019;
  background: #fff8eb;
  font-size: 11px;
  font-weight: 650;
}

.calendar-bottom {
  gap: 16px;
}

.calendar-bottom > section {
  padding: 18px;
  border-color: var(--app-border, #dce5df);
  border-radius: 14px;
  box-shadow: 0 4px 18px rgba(22, 58, 37, 0.035);
}

.calendar-bottom h2 {
  color: var(--app-text, #24332b);
  font-size: 16px;
  font-weight: 700;
}

.calendar-bottom h2 small {
  color: #6e7e74;
  font-size: 13px;
  font-weight: 500;
}

.summary-boxes {
  gap: 10px;
}

.summary-boxes span {
  padding: 14px 10px;
  border-color: #dce9df;
  border-radius: 10px;
  font-size: 22px;
  font-variant-numeric: tabular-nums;
}

.summary-boxes span small,
.summary-boxes span b {
  font-size: 12px;
}

.legend ul {
  gap: 12px;
}

.legend li {
  display: flex;
  align-items: center;
  color: #53645a;
  font-size: 13px;
}

.legend .checked_out {
  background: #3984d6;
}

.week-view article {
  border-color: #e1e9e4;
  border-radius: 10px;
  background: #fbfdfb;
}

.week-view article h3 {
  margin-top: 0;
  color: #2f4739;
  font-size: 14px;
}

.week-view span {
  margin: 8px 0;
  font-size: 12px;
}

.list-view .table-wrap {
  border: 0;
  border-radius: 0;
}

.calendar-page > main > [role='status'],
.calendar-page > main > [role='alert'] {
  margin: 0;
  padding: 12px 14px;
  border: 1px solid #dce5df;
  border-radius: 9px;
  color: #53645a;
  background: #fff;
}

@media (max-width: 1100px) {
  .calendar-filters {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .calendar-filters .view-switch {
    justify-self: start;
  }

  .calendar-bottom {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 700px) {
  .calendar-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 11px;
    padding: 14px;
  }

  .calendar-filters .today-button,
  .calendar-filters .week-picker,
  .calendar-filters .view-switch {
    grid-column: 1 / -1;
  }

  .calendar-filters .view-switch {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
  }

  .calendar-filters .view-switch button {
    padding-inline: 8px;
  }

  .main-calendar > header,
  .list-view > header {
    gap: 10px;
    padding: 12px;
  }

  .main-calendar .calendar-period {
    gap: 7px;
  }

  .main-calendar .calendar-period h2,
  .main-calendar header h2,
  .list-view > header h2 {
    font-size: 15px;
  }

  .main-calendar .export,
  .list-view > header .export {
    min-height: 36px;
    padding: 7px 9px;
    font-size: 12px;
  }

  .weekdays,
  .month-grid {
    min-width: 630px;
  }

  .month-grid article {
    min-height: 105px;
    padding: 8px;
  }

  .month-grid span {
    font-size: 11px;
  }

  .summary-boxes {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 420px) {
  .calendar-filters {
    grid-template-columns: minmax(0, 1fr);
  }

  .calendar-filters .today-button,
