    if (this.saving()) return;
    const raw = this.form.getRawValue();
    if (this.form.invalid || this.readOnly() || !raw.name.trim() || !raw.description.trim() || !Number.isInteger(raw.durationMonths) || !Number.isFinite(raw.monthlyFeeRupees)) {
