    const value = this.form.getRawValue();
    this.saving.set(true);
    this.error.set('');
    this.message.set('');
    try {
      const edited = Boolean(this.editingId());
      await this.fees.savePlan({
        ...(this.editingId() ? { id: this.editingId() } : {}),
        name: value.name.trim(),
