        duration_months: value.durationMonths,
        monthly_fee: value.monthlyFeeRupees,
        status: value.status,
      });
      this.dialogOpen.set(false);
      this.form.enable();
      await this.reload();
      this.message.set(edited ? 'Fee plan updated successfully.' : 'Fee plan added successfully.');
