  private parseCsvRows(text: string): { imported: number; skipped: number; warnings: string[] } {
    const rows: string[][] = [];
    let current = '';
    let inQuotes = false;
    for (let index = 0; index < text.length; index++) {
      const char = text[index];
      if (inQuotes) {
        if (char === '"') {
          if (text[index + 1] === '"') {
            current += '"';
            index++;
          } else {
            inQuotes = false;
          }
        } else {
          current += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          rows.push([current.trim()]);
          current = '';
        } else if (char === '\r' || char === '\n') {
          if (current.trim()) rows.push([current.trim()]);
          current = '';
        } else {
          current += char;
        }
      }
    }
    if (current.trim()) rows.push([current.trim()]);

    const parsed: { imported: number; skipped: number; warnings: string[] } = { imported: 0, skipped: 0, warnings: [] };
    const header = rows[0]?.map((cell) => cell.toLowerCase().replace(/[^a-z0-9]+/g, (m) => ' ').trim()) ?? [];
    const nameIndex = header.findIndex((column) => column === 'name' || column.includes('plan'));
    const amountIndex = header.findIndex((column) => column === 'amount' || column === 'fee' || column.includes('monthly'));
    const durationIndex = header.findIndex((column) => column === 'duration' || column.includes('months'));
    const descriptionIndex = header.findIndex((column) => column === 'description' || column.includes('note'));
    const statusIndex = header.findIndex((column) => column === 'status');
    const startIndex = Math.min(
      nameIndex === -1 ? 0 : nameIndex,
      amountIndex === -1 ? 0 : amountIndex,
      durationIndex === -1 ? 0 : durationIndex,
      descriptionIndex === -1 ? 0 : descriptionIndex,
      statusIndex === -1 ? 0 : statusIndex,
    );
    const endIndex = Math.max(
      nameIndex === -1 ? 0 : nameIndex,
      amountIndex === -1 ? 0 : amountIndex,
      durationIndex === -1 ? 0 : durationIndex,
      descriptionIndex === -1 ? 0 : descriptionIndex,
      statusIndex === -1 ? 0 : statusIndex,
    ) + 1;

    for (let rowIndex = 1; rowIndex < rows.length; rowIndex++) {
      const cells = rows[rowIndex];
      const values = cells.slice(startIndex, endIndex).map((cell) => cell.trim());
      const name = values[0] ?? '';
      const amountText = values[1] ?? '';
      const durationText = values[2] ?? '';
      const description = values[3] ?? '';
      const statusText = values[4]?.toLowerCase?.() ?? '';
      if (!name) {
        parsed.skipped++;
        parsed.warnings.push(`Row ${rowIndex + 1}: missing plan name.`);
        continue;
      }
      const amount = Number.parseFloat(amountText.replace(/,/g, ''));
      const registrationAmount = Number.parseFloat(
        (values[5] ?? '0').replace(/,/g, '')
      );
      if (!Number.isFinite(amount) || amount <= 0) {
        parsed.skipped++;
        parsed.warnings.push(`Row ${rowIndex + 1}: "${name}" needs a positive monthly fee.`);
        continue;
      }
      const duration = Number.parseInt(durationText, 10);
      const durationMonths = Number.isInteger(duration) && duration > 0 ? duration : 1;
      const normalised = statusText === 'inactive' ? 'inactive' : 'active';
      this.fees.savePlan({
        name: name.trim(),
        description: description.trim(),
        duration_months: durationMonths,
        monthly_fee: Number.parseFloat(amount.toFixed(2)) === 0
          ? 0
          : Math.round(amount * 100),
        registration_fee: Number.isFinite(registrationAmount)
          ? Math.round(registrationAmount * 100)
          : 0,
        status: normalised,
      }).catch((error) => {
        parsed.skipped++;
        parsed.warnings.push(`Row ${rowIndex + 1}: "${name}" — ${(error as Error).message}.`);
      });
      parsed.imported++;
    }
    return parsed;
  }

  private applyUpload(parsed: { imported: number; skipped: number; warnings: string[] }): void {
    if (parsed.imported === 0) {
      this.uploadError.set('No valid fee plan rows were found. Use: name, monthly amount, duration in months, status (active/inactive), and optional description.');
