import { PNG } from 'pngjs';
import fs from 'node:fs';
import path from 'node:path';

const src = PNG.sync.read(fs.readFileSync('public/branding/turf-cricket-academy-logo.png'));
const CROP = { x: 243, y: 11, w: 961, h: 853 };   // shield emblem only
const PAD = 0.58;                                  // emblem fits inside maskable safe circle
const OUT = 'public/icons';

fs.mkdirSync(OUT, { recursive: true });

// Area-average downscale of the crop, composited over white.
function render(size) {
  const out = new PNG({ width: size, height: size });
  const target = size * PAD;
  const scale = target / Math.max(CROP.w, CROP.h);
  const dw = CROP.w * scale, dh = CROP.h * scale;
  const ox = (size - dw) / 2, oy = (size - dh) / 2;

  for (let ty = 0; ty < size; ty++) {
    for (let tx = 0; tx < size; tx++) {
      const o = (ty * size + tx) << 2;
      // source rect this target pixel covers
      const sx0 = (tx - ox) / scale, sx1 = (tx + 1 - ox) / scale;
      const sy0 = (ty - oy) / scale, sy1 = (ty + 1 - oy) / scale;
      const x0 = Math.max(0, Math.floor(sx0)), x1 = Math.min(CROP.w, Math.ceil(sx1));
      const y0 = Math.max(0, Math.floor(sy0)), y1 = Math.min(CROP.h, Math.ceil(sy1));
